BEGIN;
CREATE FUNCTION legacy_assert(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF NOT coalesce(ok,false) THEN RAISE EXCEPTION 'FAIL: %',label;END IF;RAISE NOTICE 'PASS: %',label;END; $$;
CREATE FUNCTION legacy_reject(command text,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE command;EXCEPTION WHEN OTHERS THEN RAISE NOTICE 'PASS rejected: %',label;RETURN;END;RAISE EXCEPTION 'FAIL accepted: %',label;END; $$;
CREATE FUNCTION legacy_resource(provider text,parcel text,reference text,email text DEFAULT 'buyerlegacy@example.test') RETURNS jsonb LANGUAGE sql AS $$ SELECT jsonb_build_object('id',provider,'object','payment','is_live',true,'is_paid',true,'amount',3798,'amount_refunded',0,'currency','EUR','billing',jsonb_build_object('email',email),'metadata',jsonb_build_object('colis_id',parcel,'colis_ref',reference)) $$;
SELECT legacy_assert((SELECT count(*)=5 FROM legacy_payplug_payments),'Only eligible historical links were captured');
SELECT legacy_assert((SELECT count(*)=1 FROM paiements),'Migration created no payment ledger entry');
SELECT legacy_assert((SELECT paiement_date IS NULL FROM colis WHERE ref='EXP-LEGACY'),'Migration never marks an unpaid dossier paid');
SELECT legacy_assert((SELECT billing_email='buyerlegacy@example.test' FROM legacy_payplug_payments WHERE provider_id='pay_legacyPending'),'Legacy email transformation matches the historical creator');
SELECT legacy_assert(NOT has_function_privilege('authenticated','confirm_legacy_payplug_payment(jsonb)','EXECUTE'),'Browser cannot invoke historical confirmation');
SELECT legacy_assert(NOT has_table_privilege('authenticated','legacy_payplug_payments','SELECT'),'Browser cannot read historical identity snapshots');
SELECT legacy_reject($q$UPDATE legacy_payplug_payments SET amount_cents=1 WHERE provider_id='pay_legacyPending'$q$,'Frozen amount cannot be replaced');
SELECT legacy_reject($q$INSERT INTO legacy_payplug_payments SELECT * FROM legacy_payplug_payments LIMIT 1$q$,'Registry cannot enroll any post-migration link');
SELECT legacy_reject($q$SELECT confirm_legacy_payplug_payment(legacy_resource('pay_unknown','90000000-0000-4000-8000-000000000001','EXP-LEGACY'))$q$,'Unknown provider ID rejected');
SELECT legacy_reject($q$SELECT confirm_legacy_payplug_payment(legacy_resource('pay_legacyPending','90000000-0000-4000-8000-000000000002','EXP-LEGACY'))$q$,'Wrong parcel metadata rejected');
SELECT legacy_reject($q$SELECT confirm_legacy_payplug_payment(legacy_resource('pay_legacyPending','90000000-0000-4000-8000-000000000001','WRONG-REF'))$q$,'Wrong historical reference rejected');
SELECT legacy_reject($q$SELECT confirm_legacy_payplug_payment(legacy_resource('pay_legacyPending','90000000-0000-4000-8000-000000000001','EXP-LEGACY','other@example.test'))$q$,'Wrong billing customer rejected');
SELECT legacy_reject($q$SELECT confirm_legacy_payplug_payment(legacy_resource('pay_legacyPending','90000000-0000-4000-8000-000000000001','EXP-LEGACY')||'{"amount":1}')$q$,'Wrong amount rejected');
SELECT legacy_reject($q$SELECT confirm_legacy_payplug_payment(legacy_resource('pay_legacyPending','90000000-0000-4000-8000-000000000001','EXP-LEGACY')||'{"currency":"USD"}')$q$,'Wrong currency rejected');
SELECT legacy_reject($q$SELECT confirm_legacy_payplug_payment(legacy_resource('pay_legacyPending','90000000-0000-4000-8000-000000000001','EXP-LEGACY')||'{"is_paid":false}')$q$,'Unpaid resource rejected');
SELECT legacy_reject($q$SELECT confirm_legacy_payplug_payment(legacy_resource('pay_legacyPending','90000000-0000-4000-8000-000000000001','EXP-LEGACY')||'{"amount_refunded":3798}')$q$,'Refunded resource requires reconciliation');
SELECT legacy_reject($q$SELECT confirm_legacy_payplug_payment(jsonb_set(legacy_resource('pay_legacyPending','90000000-0000-4000-8000-000000000001','EXP-LEGACY'),'{metadata,quote_version}','0'))$q$,'Modern version cannot downgrade into legacy');
SELECT legacy_reject($q$UPDATE factures SET colis_id='90000000-0000-4000-8000-000000000003' WHERE id='40000000-0000-4000-8000-000000000099'$q$,'Paid historical invoice cannot be moved out of its dossier');
SELECT legacy_reject($q$UPDATE lignes SET colis_id='90000000-0000-4000-8000-000000000003' WHERE id='30000000-0000-4000-8000-000000000099'$q$,'Paid historical article cannot be moved out of its dossier');
SELECT confirm_legacy_payplug_payment(legacy_resource('pay_legacyPaid','90000000-0000-4000-8000-000000000002','EXP-PAID'));
SELECT legacy_assert((SELECT count(*)=1 FROM paiements),'Already paid historical callback creates no duplicate ledger');
SELECT legacy_assert((SELECT points=7 FROM clients WHERE id='80000000-0000-4000-8000-000000000001'),'Already paid historical callback creates no points');
SELECT legacy_assert((SELECT paiement_date='2026-01-01T00:00:00Z' FROM colis WHERE ref='EXP-PAID'),'Historical payment date is preserved');
SELECT confirm_legacy_payplug_payment(legacy_resource('pay_legacyPending','90000000-0000-4000-8000-000000000001','EXP-LEGACY'));
SELECT confirm_legacy_payplug_payment(legacy_resource('pay_legacyPending','90000000-0000-4000-8000-000000000001','EXP-LEGACY'));
SELECT legacy_assert((SELECT count(*)=1 FROM paiements WHERE provider_id='pay_legacyPending'),'Verified unpaid legacy payment records once');
SELECT legacy_assert((SELECT statut='paye' AND paiement_montant=37.98 AND paiement_date IS NOT NULL FROM colis WHERE ref='EXP-LEGACY'),'Verified legacy payment confirms exact amount');
SELECT legacy_assert((SELECT points=10 FROM clients WHERE id='80000000-0000-4000-8000-000000000001'),'Repeated legacy callback never awards duplicate points');
SELECT legacy_reject($q$UPDATE legacy_payplug_payments SET provider_verification='{}' WHERE provider_id='pay_legacyPending'$q$,'First provider verification stays immutable');
INSERT INTO lignes(colis_id,description,qte,prix_unitaire) VALUES('90000000-0000-4000-8000-000000000003','Changed after migration',1,10);
SELECT legacy_assert((SELECT invalidated_at IS NOT NULL FROM legacy_payplug_payments WHERE provider_id='pay_legacyChanged'),'Article changes invalidate historical compatibility');
SELECT legacy_reject($q$SELECT confirm_legacy_payplug_payment(legacy_resource('pay_legacyChanged','90000000-0000-4000-8000-000000000003','EXP-CHANGED','other@example.test'))$q$,'Superseded legacy quote cannot be paid');
SELECT legacy_reject($q$UPDATE legacy_payplug_payments SET invalidated_at=NULL WHERE provider_id='pay_legacyChanged'$q$,'Historical compatibility cannot be reactivated');
UPDATE colis SET devis_brouillon=true WHERE ref='EXP-DRAFT';
SELECT legacy_assert((SELECT invalidated_at IS NOT NULL FROM legacy_payplug_payments WHERE provider_id='pay_legacyDraft'),'Reopening a draft invalidates historical compatibility');
UPDATE clients SET cp='97600' WHERE id='80000000-0000-4000-8000-000000000002';
SELECT legacy_assert((SELECT invalidated_at IS NOT NULL FROM legacy_payplug_payments WHERE provider_id='pay_legacyDestination'),'Destination changes invalidate historical compatibility');
ROLLBACK;
